package com.deviceactivitytracker.utils\n\nimport android.app.ActivityManager\nimport android.content.Context\nimport android.os.Build\nimport android.os.Environment\nimport android.os.StatFs\nimport android.util.DisplayMetrics\nimport android.view.WindowManager\nimport com.deviceactivitytracker.data.model.DeviceInfo\nimport java.io.File\nimport kotlin.math.sqrt\n\nclass DeviceInfoProvider(private val context: Context) {\n    \n    fun getCompleteDeviceInfo(phoneNumber: String): DeviceInfo {\n        return DeviceInfo(\n            phoneNumber = phoneNumber,\n            deviceName = getDeviceName(),\n            manufacturer = Build.MANUFACTURER,\n            model = Build.MODEL,\n            androidVersion = Build.VERSION.SDK_INT,\n            osVersion = Build.VERSION.RELEASE,\n            cpuAbi = Build.CPU_ABI,\n            ramMemory = getTotalRAM(),\n            storageSpace = getTotalStorageSpace(),\n            screenDensity = getScreenDensity(),\n            screenResolution = getScreenResolution(),\n            isRooted = isDeviceRooted()\n        )\n    }\n    \n    private fun getDeviceName(): String {\n        return Build.DEVICE\n    }\n    \n    private fun getTotalRAM(): Long {\n        val activityManager = context.getSystemService(Context.ACTIVITY_SERVICE) as ActivityManager\n        val memInfo = ActivityManager.MemoryInfo()\n        activityManager.getMemoryInfo(memInfo)\n        return memInfo.totalMemory / (1024 * 1024) // Convert to MB\n    }\n    \n    private fun getTotalStorageSpace(): Long {\n        return try {\n            val statFs = StatFs(Environment.getDataDirectory().absolutePath)\n            val blockSize = statFs.blockSizeLong\n            val totalBlocks = statFs.blockCountLong\n            (blockSize * totalBlocks) / (1024 * 1024 * 1024) // Convert to GB\n        } catch (e: Exception) {\n            0L\n        }\n    }\n    \n    private fun getScreenDensity(): Float {\n        val displayMetrics = DisplayMetrics()\n        val windowManager = context.getSystemService(Context.WINDOW_SERVICE) as WindowManager\n        windowManager.defaultDisplay.getMetrics(displayMetrics)\n        return displayMetrics.density\n    }\n    \n    private fun getScreenResolution(): String {\n        val displayMetrics = DisplayMetrics()\n        val windowManager = context.getSystemService(Context.WINDOW_SERVICE) as WindowManager\n        windowManager.defaultDisplay.getMetrics(displayMetrics)\n        \n        val width = displayMetrics.widthPixels\n        val height = displayMetrics.heightPixels\n        val diagonalInches = calculateDiagonal(width, height, displayMetrics.xdpi, displayMetrics.ydpi)\n        \n        return \"${width}x${height} (${String.format(\"%.1f\", diagonalInches)}\\\")\"\n    }\n    \n    private fun calculateDiagonal(width: Int, height: Int, xdpi: Float, ydpi: Float): Double {\n        val widthInches = width / xdpi\n        val heightInches = height / ydpi\n        return sqrt((widthInches * widthInches + heightInches * heightInches).toDouble())\n    }\n    \n    private fun isDeviceRooted(): Boolean {\n        return try {\n            val paths = arrayOf(\n                \"/system/app/Superuser.apk\",\n                \"/system/xbin/su\",\n                \"/system/bin/su\",\n                \"/data/local/xbin/su\",\n                \"/data/local/bin/su\",\n                \"/system/sd/xbin/su\",\n                \"/system/bin/failsafe/su\",\n                \"/data/local/su\",\n                \"/su/bin/su\"\n            )\n            paths.any { File(it).exists() }\n        } catch (e: Exception) {\n            false\n        }\n    }\n}\n